import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';// Simple test script to verify FastAPI endpoint connectivity\nclass ApiEndpointTester {\n  static Future<void> testApiConnectivity() async {\n    try {\n      // Load environment variables\n      await dotenv.load(fileName: '.env');\n      \n      // Get FastAPI endpoint\n      final fastApiUrl = dotenv.env['FASTAPI_ENDPOINT'];\n      if (fastApiUrl == null || fastApiUrl.isEmpty) {\n        print('❌ FASTAPI_ENDPOINT not found in .env file');\n        return;\n      }\n      \n      print('🔍 Testing FastAPI connectivity...');\n      print('   FastAPI URL: $fastApiUrl');\n      \n      // Test basic connectivity\n      try {\n        final response = await http.get(\n          Uri.parse('$fastApiUrl/health'),\n          headers: {\n            'Content-Type': 'application/json',\n            'Accept': 'application/json',\n          },\n        ).timeout(const Duration(seconds: 10));\n        \n        if (response.statusCode == 200) {\n          print('✅ FastAPI server is reachable');\n          print('   Response: ${response.body}');\n        } else {\n          print('⚠️  FastAPI server responded with status: ${response.statusCode}');\n          print('   Response: ${response.body}');\n        }\n      } catch (e) {\n        print('❌ Failed to connect to FastAPI server: $e');\n        print('   Please check:');\n        print('   - FastAPI server is running on $fastApiUrl');\n        print('   - Network connectivity');\n        print('   - Firewall settings');\n      }\n      \n      // Test profile update endpoint with correct path\n      print('\\n🔍 Testing profile update endpoint...');\n      final testUserId = 'test-user-id';\n      final updateEndpoint = '$fastApiUrl/users/$testUserId';\n      print('   Update URL: $updateEndpoint');\n      \n      try {\n        final response = await http.options(\n          Uri.parse(updateEndpoint),\n          headers: {\n            'Content-Type': 'application/json',\n            'Accept': 'application/json',\n          },\n        ).timeout(const Duration(seconds: 10));\n        \n        if (response.statusCode == 200 || response.statusCode == 405) {\n          print('✅ Profile update endpoint is reachable');\n          print('   Status: ${response.statusCode}');\n        } else {\n          print('⚠️  Profile update endpoint responded with status: ${response.statusCode}');\n        }\n      } catch (e) {\n        print('❌ Failed to reach profile update endpoint: $e');\n      }\n      \n    } catch (e) {\n      print('❌ Error during API testing: $e');\n    }\n  }\n  \n  static Future<void> testProfileUpdate() async {\n    try {\n      await dotenv.load(fileName: '.env');\n      \n      final fastApiUrl = dotenv.env['FASTAPI_ENDPOINT'];\n      if (fastApiUrl == null || fastApiUrl.isEmpty) {\n        print('❌ FASTAPI_ENDPOINT not found in .env file');\n        return;\n      }\n      \n      print('\\n🔍 Testing profile update with sample data...');\n      \n      final testUserId = 'test-user-id';\n      final testData = {\n        'address': 'Test Address 123',\n        'idDocumentUrl': 'https://example.com/test-id.jpg',\n        'role': 'Rep',\n        'verificationStatus': 'pending',\n      };\n      \n      // Test with PATCH method to match your server\n      final response = await http.patch(\n        Uri.parse('$fastApiUrl/users/$testUserId'),\n        headers: {\n          'Content-Type': 'application/json',\n          'Accept': 'application/json',\n          'Authorization': 'Bearer test_token',\n        },\n        body: jsonEncode(testData),\n      ).timeout(const Duration(seconds: 30));\n      \n      print('   Status Code: ${response.statusCode}');\n      print('   Response Body: ${response.body}');\n      \n      if (response.statusCode == 200 || response.statusCode == 201) {\n        print('✅ Profile update endpoint is working correctly');\n      } else if (response.statusCode == 404) {\n        print('❌ Profile update endpoint not found (404)');\n        print('   This means the PATCH /users/{user_id} endpoint is missing');\n      } else if (response.statusCode == 401) {\n        print('⚠️  Authentication required (401) - this is expected for test data');\n      } else if (response.statusCode == 422) {\n        print('⚠️  Validation error (422) - check request data format');\n      } else {\n        print('⚠️  Unexpected response from profile update endpoint');\n      }\n      \n    } catch (e) {\n      print('❌ Error testing profile update: $e');\n    }\n  }\n}\n\nvoid main() async {\n  print('🚀 FieldForce API Endpoint Tester');\n  print('=' * 50);\n  \n  await ApiEndpointTester.testApiConnectivity();\n  await ApiEndpointTester.testProfileUpdate();\n  \n  print('\\n' + '=' * 50);\n  print('✅ API endpoint testing completed');\n  print('\\n📋 Expected endpoint: PATCH /users/{user_id}');\n  print('   Your server should have this endpoint to work with the app.');\n}\n